  "/lib/data.js": {
    "code": "// Mock database for the HR Management App
import { v4 as uuidv4 } from 'uuid';

// Initial data
let departments = [
  {
    id: "dept-1",
    name: "Engineering",
    teamLeadId: "emp-1"
  },
  {
    id: "dept-2",
    name: "Marketing",
    teamLeadId: "emp-3"
  },
  {
    id: "dept-3",
    name: "Human Resources",
    teamLeadId: "emp-5"
  }
];

let employees = [
  {
    id: "emp-1",
    name: "John Doe",
    email: "john.doe@tericsoft.com",
    departmentId: "dept-1",
    phoneNumber: "555-123-4567",
    designation: "Senior Engineer"
  },
  {
    id: "emp-2",
    name: "Jane Smith",
    email: "jane.smith@tericsoft.com",
    departmentId: "dept-1",
    phoneNumber: "555-234-5678",
    designation: "Software Engineer"
  },
  {
    id: "emp-3",
    name: "Emily Johnson",
    email: "emily.johnson@tericsoft.com",
    departmentId: "dept-2",
    phoneNumber: "555-345-6789",
    designation: "Marketing Manager"
  },
  {
    id: "emp-4",
    name: "Michael Brown",
    email: "michael.brown@tericsoft.com",
    departmentId: "dept-2",
    phoneNumber: "555-456-7890",
    designation: "Marketing Specialist"
  },
  {
    id: "emp-5",
    name: "Sarah Wilson",
    email: "sarah.wilson@tericsoft.com",
    departmentId: "dept-3",
    phoneNumber: "555-567-8901",
    designation: "HR Director"
  }
];

const users = [
  {
    id: "user-1",
    email: "admin@tericsoft.com",
    password: "tericsoft@123",
    role: "admin"
  }
];

// Department functions
export const getDepartments = () => {
  return [...departments];
};

export const getDepartmentById = (id) => {
  return departments.find(dept => dept.id === id) || null;
};

export const addDepartment = (departmentData) => {
  const newDepartment = {
    id: `dept-${uuidv4()}`,
    ...departmentData
  };

  departments.push(newDepartment);
  return newDepartment;
};

export const updateDepartment = (id, departmentData) => {
  const index = departments.findIndex(dept => dept.id === id);
  if (index === -1) return null;

  departments[index] = { ...departments[index], ...departmentData };
  return departments[index];
};

export const deleteDepartment = (id) => {
  const index = departments.findIndex(dept => dept.id === id);
  if (index === -1) return false;

  // First update any employees in this department
  employees = employees.map(emp => {
    if (emp.departmentId === id) {
      return { ...emp, departmentId: null };
    }
    return emp;
  });

  // Then delete the department
  departments = departments.filter(dept => dept.id !== id);
  return true;
};

export const getDepartmentMembers = (departmentId) => {
  return employees.filter(emp => emp.departmentId === departmentId);
};

export const getDepartmentTeamLead = (departmentId) => {
  const department = departments.find(dept => dept.id === departmentId);
  if (!department || !department.teamLeadId) return null;

  return employees.find(emp => emp.id === department.teamLeadId) || null;
};

// Employee functions
export const getEmployees = () => {
  return [...employees];
};

export const getEmployeeById = (id) => {
  return employees.find(emp => emp.id === id) || null;
};

export const addEmployee = (employeeData) => {
  const newEmployee = {
    id: `emp-${uuidv4()}`,
    ...employeeData
  };

  employees.push(newEmployee);
  return newEmployee;
};

export const updateEmployee = (id, employeeData) => {
  const index = employees.findIndex(emp => emp.id === id);
  if (index === -1) return null;

  employees[index] = { ...employees[index], ...employeeData };
  return employees[index];
};

export const deleteEmployee = (id) => {
  const index = employees.findIndex(emp => emp.id === id);
  if (index === -1) return false;

  // Update any departments where this employee is the team lead
  departments = departments.map(dept => {
    if (dept.teamLeadId === id) {
      return { ...dept, teamLeadId: null };
    }
    return dept;
  });

  employees = employees.filter(emp => emp.id !== id);
  return true;
};

// Auth functions
export const authenticateUser = (email, password) => {
  const user = users.find(user => user.email === email && user.password === password);
  if (!user) return null;

  // Don't return the password
  const { password: _, ...userWithoutPassword } = user;
  return userWithoutPassword;
};",
