  },
  "/components/Layout.js": {
    "code": "import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { logout, isAuthenticated } from '../lib/auth';
import { FiMenu, FiX, FiLogOut, FiHome, FiUsers, FiLayers } from 'react-icons/fi';

export default function Layout({ children }) {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const router = useRouter();

  useEffect(() => {
    setIsLoggedIn(isAuthenticated());
  }, []);

  const handleLogout = () => {
    logout();
    router.push('/login');
  };

  if (!isLoggedIn && router.pathname !== '/login') {
    return <div className="p-8 text-center">Loading...</div>;
  }

  if (router.pathname === '/login') {
    return <main className="bg-gray-50 min-h-screen">{children}</main>;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <header className="bg-primary-700 text-white shadow-md">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center">
              <Link href="/">
                <a className="flex items-center">
                  <span className="text-xl font-bold tracking-tight">TericSoft HR</span>
                </a>
              </Link>
            </div>

            {/* Desktop menu */}
            <nav className="hidden md:flex space-x-8">
              <Link href="/">
                <a className="flex items-center px-3 py-2 text-sm font-medium hover:bg-primary-600 rounded-md transition-colors duration-150 ease-in-out">
                  <FiHome className="mr-1.5" /> Dashboard
                </a>
              </Link>
              <Link href="/departments">
                <a className="flex items-center px-3 py-2 text-sm font-medium hover:bg-primary-600 rounded-md transition-colors duration-150 ease-in-out">
                  <FiLayers className="mr-1.5" /> Departments
                </a>
              </Link>
              <Link href="/employees">
                <a className="flex items-center px-3 py-2 text-sm font-medium hover:bg-primary-600 rounded-md transition-colors duration-150 ease-in-out">
                  <FiUsers className="mr-1.5" /> Employees
                </a>
              </Link>
              <button 
                onClick={handleLogout} 
                className="flex items-center px-3 py-2 text-sm font-medium hover:bg-primary-600 rounded-md transition-colors duration-150 ease-in-out"
              >
                <FiLogOut className="mr-1.5" /> Logout
              </button>
            </nav>

            {/* Mobile menu button */}
            <div className="md:hidden">
              <button
                onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                className="inline-flex items-center justify-center p-2 rounded-md text-white hover:bg-primary-600 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-white"
              >
                {isMobileMenuOpen ? (
                  <FiX className="block h-6 w-6" aria-hidden="true" />
                ) : (
                  <FiMenu className="block h-6 w-6" aria-hidden="true" />
                )}
              </button>
            </div>
          </div>
        </div>

        {/* Mobile menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden slide-in">
            <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
              <Link href="/">
                <a className="flex items-center px-3 py-2 text-sm font-medium hover:bg-primary-600 rounded-md transition-colors duration-150 ease-in-out">
                  <FiHome className="mr-1.5" /> Dashboard
                </a>
              </Link>
              <Link href="/departments">
                <a className="flex items-center px-3 py-2 text-sm font-medium hover:bg-primary-600 rounded-md transition-colors duration-150 ease-in-out">
                  <FiLayers className="mr-1.5" /> Departments
                </a>
              </Link>
              <Link href="/employees">
                <a className="flex items-center px-3 py-2 text-sm font-medium hover:bg-primary-600 rounded-md transition-colors duration-150 ease-in-out">
                  <FiUsers className="mr-1.5" /> Employees
                </a>
              </Link>
              <button 
                onClick={handleLogout} 
                className="flex w-full items-center px-3 py-2 text-sm font-medium hover:bg-primary-600 rounded-md transition-colors duration-150 ease-in-out"
              >
                <FiLogOut className="mr-1.5" /> Logout
              </button>
            </div>
          </div>
        )}
      </header>

      <main className="flex-grow max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {children}
      </main>

      <footer className="bg-white shadow-inner py-4">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <p className="text-center text-sm text-gray-500">
            © {new Date().getFullYear()} TericSoft HR Management. All rights reserved.
          </p>
        </div>
      </footer>
    </div>
  );
}",
