  },
  "/pages/employees/new.js": {
    "code": "import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { FiArrowLeft, FiSave } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { addEmployee, getDepartments } from '../../lib/data';
import { Button } from '../../components/Button';
import { Input } from '../../components/Input';
import { Select } from '../../components/Select';
import { Label } from '../../components/Label';
import { Card } from '../../components/Card';

export default function NewEmployee() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    departmentId: '',
    phoneNumber: '',
    designation: ''
  });
  const [departments, setDepartments] = useState([]);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const router = useRouter();

  useEffect(() => {
    loadDepartments();
  }, []);

  const loadDepartments = () => {
    try {
      const departmentData = getDepartments();
      setDepartments(departmentData);
    } catch (error) {
      console.error('Failed to load departments:', error);
      toast.error('Failed to load departments');
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Name is required';
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'Email is invalid';
    }

    if (!formData.phoneNumber.trim()) {
      newErrors.phoneNumber = 'Phone number is required';
    }

    if (!formData.designation.trim()) {
      newErrors.designation = 'Designation is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsSubmitting(true);
    try {
      const newEmployee = addEmployee(formData);

      toast.success(`Employee "${newEmployee.name}" has been created`);
      router.push('/employees');
    } catch (error) {
      console.error('Failed to create employee:', error);
      toast.error('Failed to create employee');
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto fade-in">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push('/employees')}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Employees
        </Button>
        <h1 className="text-2xl font-bold">Add New Employee</h1>
      </div>

      <Card>
        <form onSubmit={handleSubmit}>
          <Card.Content className="space-y-6">
            <div className="space-y-2">
              <Label htmlFor="name">
                Full Name <span className="text-red-500">*</span>
              </Label>
              <Input
                id="name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="John Doe"
                className={errors.name ? 'border-red-500' : ''}
              />
              {errors.name && (
                <p className="text-red-500 text-sm mt-1">{errors.name}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="email">
                Email <span className="text-red-500">*</span>
              </Label>
              <Input
                id="email"
                name="email"
                type="email"
                value={formData.email}
                onChange={handleChange}
                placeholder="john.doe@tericsoft.com"
                className={errors.email ? 'border-red-500' : ''}
              />
              {errors.email && (
                <p className="text-red-500 text-sm mt-1">{errors.email}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="phoneNumber">
                Phone Number <span className="text-red-500">*</span>
              </Label>
              <Input
                id="phoneNumber"
                name="phoneNumber"
                value={formData.phoneNumber}
                onChange={handleChange}
                placeholder="555-123-4567"
                className={errors.phoneNumber ? 'border-red-500' : ''}
              />
              {errors.phoneNumber && (
                <p className="text-red-500 text-sm mt-1">{errors.phoneNumber}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="designation">
                Designation <span className="text-red-500">*</span>
              </Label>
              <Input
                id="designation"
                name="designation"
                value={formData.designation}
                onChange={handleChange}
                placeholder="Software Engineer"
                className={errors.designation ? 'border-red-500' : ''}
              />
              {errors.designation && (
                <p className="text-red-500 text-sm mt-1">{errors.designation}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="departmentId">Department</Label>
              <Select
                id="departmentId"
                name="departmentId"
                value={formData.departmentId}
                onChange={handleChange}
              >
                <option value="">-- Select Department (Optional) --</option>
                {departments.map(dept => (
                  <option key={dept.id} value={dept.id}>
                    {dept.name}
                  </option>
                ))}
              </Select>
            </div>
          </Card.Content>

          <Card.Footer className="flex justify-end space-x-2 border-t pt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => router.push('/employees')}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center"
            >
              <FiSave className="mr-2" />
              {isSubmitting ? 'Creating...' : 'Create Employee'}
            </Button>
          </Card.Footer>
        </form>
      </Card>
    </div>
  );
}",
