                <div>
                  <p className="font-medium">Not a Team Lead</p>
                  <p className="text-sm text-gray-500">
                    This employee is not currently designated as a team lead.
                  </p>
                </div>
              </div>
            )}
          </Card.Content>
          {department && department.teamLeadId !== employee.id && (
            <Card.Footer>
              <Link href={`/departments/${department.id}/edit`}>
                <a className="text-primary-600 hover:text-primary-700 text-sm font-medium">
                  Assign as Team Lead →
                </a>
              </Link>
            </Card.Footer>
          )}
        </Card>

        {/* Additional Information */}
        <Card className="md:col-span-3">
          <Card.Header>
            <Card.Title>Additional Information</Card.Title>
          </Card.Header>
          <Card.Content>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              <div>
                <h3 className="text-sm font-medium text-gray-500">Employee ID</h3>
                <p className="mt-1">{employee.id}</p>
              </div>
              <div>
                <h3 className="text-sm font-medium text-gray-500">Full Name</h3>
                <p className="mt-1">{employee.name}</p>
              </div>
              <div>
                <h3 className="text-sm font-medium text-gray-500">Position</h3>
                <p className="mt-1">{employee.designation}</p>
              </div>
              <div>
                <h3 className="text-sm font-medium text-gray-500">Department</h3>
                <p className="mt-1">{department ? department.name : 'None'}</p>
              </div>
              <div>
                <h3 className="text-sm font-medium text-gray-500">Email</h3>
                <p className="mt-1">{employee.email}</p>
              </div>
              <div>
                <h3 className="text-sm font-medium text-gray-500">Phone</h3>
                <p className="mt-1">{employee.phoneNumber}</p>
              </div>
            </div>
          </Card.Content>
        </Card>
      </div>

      {/* Delete Confirmation Modal */}
      <Modal
        isOpen={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        title="Delete Employee"
        description="Are you sure you want to delete this employee? This action cannot be undone."
        footer={
          <>
            <Button 
              variant="outline" 
              onClick={() => setIsDeleteModalOpen(false)}
              disabled={isDeleting}
            >
              Cancel
            </Button>
            <Button 
              variant="destructive" 
              onClick={handleDelete}
              disabled={isDeleting}
            >
              {isDeleting ? 'Deleting...' : 'Delete Employee'}
            </Button>
          </>
        }
      >
        <div className="text-sm text-gray-500">
          <p>
            This will permanently delete the employee 
            <span className="font-semibold text-gray-700"> {employee.name} </span>
            from the system.
          </p>
          {department && department.teamLeadId === employee.id && (
            <div className="bg-yellow-50 p-3 rounded mt-3 text-yellow-800 flex items-start">
              <FiCheck className="h-5 w-5 mr-2 mt-0.5 flex-shrink-0" />
              <p>
                This employee is currently the Team Lead for {department.name}.
                Deleting them will remove their team lead status.
              </p>
            </div>
          )}
        </div>
      </Modal>
    </div>
  );
}",
    "active": true
  },
  "/pages/employees/[id]/edit.js": {
    "code": "import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { FiArrowLeft, FiSave } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { 
  getEmployeeById, 
  updateEmployee, 
  getDepartments 
} from '../../../lib/data';
import { Button } from '../../../components/Button';
import { Input } from '../../../components/Input';
import { Select } from '../../../components/Select';
import { Label } from '../../../components/Label';
import { Card } from '../../../components/Card';

export default function EditEmployee() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    departmentId: '',
    phoneNumber: '',
    designation: ''
  });
  const [originalData, setOriginalData] = useState(null);
  const [departments, setDepartments] = useState([]);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [loading, setLoading] = useState(true);
  const router = useRouter();
  const { id } = router.query;

  useEffect(() => {
    if (id) {
      loadData();
    }
  }, [id]);

  const loadData = async () => {
    try {
      // Load employee data
      const employeeData = getEmployeeById(id);

      if (!employeeData) {
        toast.error('Employee not found');
        router.push('/employees');
        return;
      }

      // Load departments for selection
      const departmentData = getDepartments();

      setFormData({
        name: employeeData.name,
        email: employeeData.email,
        departmentId: employeeData.departmentId || '',
        phoneNumber: employeeData.phoneNumber,
        designation: employeeData.designation
      });
      setOriginalData(employeeData);
      setDepartments(departmentData);
    } catch (error) {
      console.error('Failed to load data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Name is required';
    }

