    "code": "import Image from 'next/image';
import { cn } from '../lib/utils';

export function Avatar({ 
  src = null, 
  alt = "Avatar", 
  size = "md", 
  className,
  fallback,
  ...props 
}) {
  const sizeClass = {
    sm: "h-8 w-8",
    md: "h-10 w-10",
    lg: "h-12 w-12",
    xl: "h-16 w-16"
  };

