import { logout, isAuthenticated, getUser } from '../lib/auth';
import { FiMenu, FiX, FiLogOut, FiHome, FiUsers, FiLayers } from 'react-icons/fi';

export default function Layout({ children }) {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState(null);
  const router = useRouter();

  useEffect(() => {
    // Check authentication status and update state
    const checkAuth = () => {
      const authStatus = isAuthenticated();
      setIsLoggedIn(authStatus);
      setUser(getUser());

      // If not logged in and not on login page, redirect to login
      if (!authStatus && router.pathname !== '/login') {
        router.push('/login');
      }
    };

    checkAuth();

    // Listen for route changes to recheck auth
    const handleRouteChange = () => {
      checkAuth();
    };

    router.events.on('routeChangeComplete', handleRouteChange);
    return () => {
      router.events.off('routeChangeComplete', handleRouteChange);
    };
  }, [router]);

  const handleLogout = () => {
    logout();
    router.push('/login');
  };

  if (router.pathname === '/login') {
    return <main className="bg-gray-50 min-h-screen">{children}</main>;
  }

  if (!isLoggedIn && router.pathname !== '/login') {
    return null; // Don't show anything while redirecting
