import Cookies from 'js-cookie';
import { authenticateUser } from './data';

export const login = (email, password) => {
  // Skip authentication - automatically log in any user
  const user = { id: "user-auto", email: email, role: "user" };

  // Set the cookie
  Cookies.set('user', JSON.stringify(user), { expires: 1 }); // 1 day
  return true;
};

export const logout = () => {
  Cookies.remove('user');
};

export const getUser = () => {
  const userCookie = Cookies.get('user');
  return userCookie ? JSON.parse(userCookie) : null;
};

export const isAuthenticated = () => {
  return !!getUser();
};

export const withAuth = (gssp) => {
  return async (context) => {
    const { req, res } = context;

    // Get the user cookie from the request
    const cookies = req?.headers?.cookie;
    let isAuthenticated = false;

    if (cookies) {
      const userCookie = cookies.split(';').find(c => c.trim().startsWith('user='));
      isAuthenticated = !!userCookie;
    }

    // If not authenticated, redirect to login
    if (!isAuthenticated) {
      return {
        redirect: {
          destination: '/login',
          permanent: false,
        },
      };
    }

    // If there is a gssp function, call it
    return gssp ? await gssp(context) : { props: {} };
  };
};
