              <Link href="/">
                <a className="flex items-center px-3 py-2 text-sm font-medium hover:bg-primary-600 rounded-md transition-colors duration-150 ease-in-out">
                  <FiHome className="mr-1.5" /> Dashboard
                </a>
              </Link>
              <Link href="/departments">
                <a className="flex items-center px-3 py-2 text-sm font-medium hover:bg-primary-600 rounded-md transition-colors duration-150 ease-in-out">
                  <FiLayers className="mr-1.5" /> Departments
                </a>
              </Link>
              <Link href="/employees">
                <a className="flex items-center px-3 py-2 text-sm font-medium hover:bg-primary-600 rounded-md transition-colors duration-150 ease-in-out">
                  <FiUsers className="mr-1.5" /> Employees
                </a>
              </Link>
              <button 
                onClick={handleLogout} 
                className="flex items-center px-3 py-2 text-sm font-medium hover:bg-primary-600 rounded-md transition-colors duration-150 ease-in-out"
              >
                <FiLogOut className="mr-1.5" /> Logout
              </button>
            </nav>

            {/* Mobile menu button */}
            <div className="md:hidden">
              <button
                onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                className="inline-flex items-center justify-center p-2 rounded-md text-white hover:bg-primary-600 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-white"
