    "code": "import { useState, useEffect } from 'react';
import Link from 'next/link';
import { FiFolderPlus, FiSearch } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { 
  getDepartments, 
  getDepartmentMembers, 
  getDepartmentTeamLead,
  deleteDepartment
} from '../../lib/data';
import { Button } from '../../components/Button';
import { Input } from '../../components/Input';
import { DepartmentCard } from '../../components/DepartmentCard';
import { EmptyState } from '../../components/EmptyState';
import { Modal } from '../../components/Modal';

export default function Departments() {
  const [departments, setDepartments] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [departmentToDelete, setDepartmentToDelete] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    loadDepartments();
  }, []);

  const loadDepartments = () => {
    try {
      const deptData = getDepartments();

      // Enhance with member count and team lead data
      const enhancedDepts = deptData.map(dept => {
        const memberCount = getDepartmentMembers(dept.id).length;
        const teamLead = getDepartmentTeamLead(dept.id);

        return {
          ...dept,
          memberCount,
          teamLead
        };
      });

      setDepartments(enhancedDepts);
    } catch (error) {
      toast.error('Failed to load departments');
      console.error(error);
    }
  };

  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
  };

  const handleDeleteClick = (department) => {
    setDepartmentToDelete(department);
    setIsDeleteModalOpen(true);
  };

  const handleEditClick = (department) => {
    // Navigate to edit page
    window.location.href = `/departments/${department.id}/edit`;
  };

  const confirmDelete = async () => {
    if (!departmentToDelete) return;

    setIsLoading(true);
    try {
      const success = deleteDepartment(departmentToDelete.id);

      if (success) {
        toast.success(`${departmentToDelete.name} has been deleted`);
        loadDepartments();
      } else {
        toast.error('Failed to delete department');
      }
    } catch (error) {
      toast.error('An error occurred while deleting');
      console.error(error);
    } finally {
      setIsLoading(false);
      setIsDeleteModalOpen(false);
      setDepartmentToDelete(null);
    }
  };

  // Filter departments based on search
  const filteredDepartments = departments.filter(dept =>
    dept.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <h1 className="text-2xl font-bold">Departments</h1>
        <Link href="/departments/new">
          <a>
            <Button className="w-full sm:w-auto flex items-center justify-center">
              <FiFolderPlus className="mr-2" />
              Add Department
            </Button>
          </a>
        </Link>
      </div>

      {/* Search */}
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
          <FiSearch />
        </div>
        <Input
          type="text"
          placeholder="Search departments..."
          value={searchQuery}
          onChange={handleSearchChange}
          className="pl-10"
        />
      </div>

      {/* Department Grid */}
      {departments.length === 0 ? (
        <EmptyState 
          title="No departments yet"
          description="Get started by creating your first department"
          action={() => window.location.href = '/departments/new'}
        />
      ) : filteredDepartments.length === 0 ? (
        <EmptyState 
          title="No matching departments"
          description="Try a different search term"
          action={() => setSearchQuery('')}
          actionText="Clear Search"
        />
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredDepartments.map((dept) => (
            <DepartmentCard
              key={dept.id}
              department={dept}
              memberCount={dept.memberCount}
              teamLead={dept.teamLead}
              onEdit={handleEditClick}
              onDelete={handleDeleteClick}
            />
          ))}
        </div>
      )}

      {/* Delete Confirmation Modal */}
      <Modal
        isOpen={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        title="Delete Department"
        description="Are you sure you want to delete this department? This action cannot be undone."
        footer={
          <>
            <Button 
              variant="outline" 
              onClick={() => setIsDeleteModalOpen(false)}
              disabled={isLoading}
            >
              Cancel
            </Button>
            <Button 
              variant="destructive" 
              onClick={confirmDelete}
              disabled={isLoading}
            >
              {isLoading ? 'Deleting...' : 'Delete'}
            </Button>
          </>
        }
      >
        {departmentToDelete && (
          <div className="text-sm text-gray-500">
            <p>
              This will permanently delete the department 
              <span className="font-semibold text-gray-700"> {departmentToDelete.name} </span>
              and remove all department associations from employees.
            </p>
            <p className="mt-2">
              The employees will not be deleted, but they will no longer be associated with this department.
            </p>
          </div>
        )}
      </Modal>
    </div>
  );
