  "/pages/employees/index.js": {
    "code": "import { useState, useEffect } from 'react';
import Link from 'next/link';
import { FiUserPlus, FiSearch, FiFilter, FiX } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { 
  getEmployees, 
  getDepartments,
  getDepartmentById,
  deleteEmployee
} from '../../lib/data';
import { Button } from '../../components/Button';
import { Input } from '../../components/Input';
import { Select } from '../../components/Select';
import { EmployeeCard } from '../../components/EmployeeCard';
import { EmptyState } from '../../components/EmptyState';
import { Modal } from '../../components/Modal';

export default function Employees() {
  const [employees, setEmployees] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [departmentFilter, setDepartmentFilter] = useState('');
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [employeeToDelete, setEmployeeToDelete] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = () => {
    try {
      const employeeData = getEmployees();
      const departmentData = getDepartments();

      // Enhance employees with department data
      const enhancedEmployees = employeeData.map(emp => {
        const department = emp.departmentId 
          ? getDepartmentById(emp.departmentId) 
          : null;

        return {
          ...emp,
          department
        };
      });

      setEmployees(enhancedEmployees);
      setDepartments(departmentData);
    } catch (error) {
      toast.error('Failed to load data');
      console.error(error);
    }
  };

  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
  };

  const handleDepartmentFilterChange = (e) => {
    setDepartmentFilter(e.target.value);
  };

  const clearFilters = () => {
    setSearchQuery('');
    setDepartmentFilter('');
  };

  const handleDeleteClick = (employee) => {
    setEmployeeToDelete(employee);
    setIsDeleteModalOpen(true);
  };

  const handleEditClick = (employee) => {
    // Navigate to edit page
    window.location.href = `/employees/${employee.id}/edit`;
  };

  const confirmDelete = async () => {
    if (!employeeToDelete) return;

    setIsLoading(true);
    try {
      const success = deleteEmployee(employeeToDelete.id);

      if (success) {
        toast.success(`${employeeToDelete.name} has been deleted`);
        loadData();
      } else {
        toast.error('Failed to delete employee');
      }
    } catch (error) {
      toast.error('An error occurred while deleting');
      console.error(error);
    } finally {
      setIsLoading(false);
      setIsDeleteModalOpen(false);
      setEmployeeToDelete(null);
    }
  };

  // Filter employees based on search and department filter
  const filteredEmployees = employees.filter(emp => {
    const matchesSearch = emp.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          emp.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          emp.designation.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesDepartment = !departmentFilter || emp.departmentId === departmentFilter;

    return matchesSearch && matchesDepartment;
  });

  const hasActiveFilters = searchQuery || departmentFilter;

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <h1 className="text-2xl font-bold">Employees</h1>
        <Link href="/employees/new">
          <a>
            <Button className="w-full sm:w-auto flex items-center justify-center">
              <FiUserPlus className="mr-2" />
              Add Employee
            </Button>
          </a>
        </Link>
      </div>

      {/* Search and Filter */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="sm:col-span-2 relative">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
            <FiSearch />
          </div>
          <Input
            type="text"
            placeholder="Search employees by name, email, or designation..."
            value={searchQuery}
            onChange={handleSearchChange}
            className="pl-10"
          />
        </div>

        <div className="relative">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
            <FiFilter />
          </div>
          <Select
            value={departmentFilter}
            onChange={handleDepartmentFilterChange}
            className="pl-10"
          >
            <option value="">All Departments</option>
            {departments.map(dept => (
              <option key={dept.id} value={dept.id}>
                {dept.name}
              </option>
            ))}
          </Select>
        </div>
      </div>

      {/* Filter indicator */}
      {hasActiveFilters && (
        <div className="flex items-center bg-gray-100 px-4 py-2 rounded-md">
          <span className="text-sm text-gray-600 mr-2">Filters applied:</span>
          {searchQuery && (
            <span className="bg-primary-100 text-primary-800 text-xs px-2 py-1 rounded-full flex items-center mr-2">
              Search: "{searchQuery}"
              <button 
                onClick={() => setSearchQuery('')}
                className="ml-1 text-primary-600 hover:text-primary-800"
              >
                <FiX size={14} />
              </button>
            </span>
          )}
          {departmentFilter && (
            <span className="bg-primary-100 text-primary-800 text-xs px-2 py-1 rounded-full flex items-center mr-2">
              Department: {departments.find(d => d.id === departmentFilter)?.name}
              <button 
                onClick={() => setDepartmentFilter('')}
                className="ml-1 text-primary-600 hover:text-primary-800"
              >
                <FiX size={14} />
              </button>
            </span>
          )}
          <button 
            onClick={clearFilters}
            className="text-xs text-gray-500 hover:text-gray-700 ml-auto"
          >
            Clear all
          </button>
        </div>
      )}

      {/* Employee Grid */}
      {employees.length === 0 ? (
        <EmptyState 
          title="No employees yet"
          description="Get started by adding your first employee"
          action={() => window.location.href = '/employees/new'}
        />
      ) : filteredEmployees.length === 0 ? (
        <EmptyState 
          title="No matching employees"
          description="Try different search terms or filters"
          action={clearFilters}
          actionText="Clear Filters"
        />
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredEmployees.map((emp) => (
            <EmployeeCard
              key={emp.id}
              employee={emp}
              department={emp.department}
              onEdit={handleEditClick}
              onDelete={handleDeleteClick}
            />
          ))}
        </div>
      )}

      {/* Delete Confirmation Modal */}
      <Modal
        isOpen={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        title="Delete Employee"
        description="Are you sure you want to delete this employee? This action cannot be undone."
        footer={
          <>
            <Button 
              variant="outline" 
              onClick={() => setIsDeleteModalOpen(false)}
              disabled={isLoading}
            >
              Cancel
            </Button>
            <Button 
              variant="destructive" 
              onClick={confirmDelete}
              disabled={isLoading}
            >
              {isLoading ? 'Deleting...' : 'Delete'}
            </Button>
          </>
        }
      >
        {employeeToDelete && (
          <div className="text-sm text-gray-500">
            <p>
              This will permanently delete the employee 
              <span className="font-semibold text-gray-700"> {employeeToDelete.name} </span>
              from the system.
            </p>
            {employeeToDelete.department && (
              <p className="mt-2">
                They will also be removed from the {employeeToDelete.department.name} department.
              </p>
            )}
          </div>
        )}
      </Modal>
    </div>
  );
}",
    "active": true
  },
