  "/pages/employees/[id]/index.js": {
    "code": "import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { 
  FiArrowLeft, FiMail, FiPhone, FiBriefcase, 
  FiEdit, FiTrash2, FiCheck, FiX
} from 'react-icons/fi';
import { toast } from 'react-toastify';
import { 
  getEmployeeById, 
  getDepartmentById,
  deleteEmployee
} from '../../../lib/data';
import { Button } from '../../../components/Button';
import { Card } from '../../../components/Card';
import { Avatar } from '../../../components/Avatar';
import { Modal } from '../../../components/Modal';

export default function EmployeeDetails() {
  const [employee, setEmployee] = useState(null);
  const [department, setDepartment] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const router = useRouter();
  const { id } = router.query;

  useEffect(() => {
    if (id) {
      loadEmployeeData();
    }
  }, [id]);

  const loadEmployeeData = () => {
    try {
      const employeeData = getEmployeeById(id);

      if (!employeeData) {
        toast.error('Employee not found');
        router.push('/employees');
        return;
      }

      // Load department if exists
      let departmentData = null;
      if (employeeData.departmentId) {
        departmentData = getDepartmentById(employeeData.departmentId);
      }

      setEmployee(employeeData);
      setDepartment(departmentData);
    } catch (error) {
      console.error('Failed to load employee data:', error);
      toast.error('Failed to load employee data');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    setIsDeleting(true);

    try {
      const success = deleteEmployee(id);

      if (success) {
        toast.success(`Employee "${employee.name}" has been deleted`);
        router.push('/employees');
      } else {
        throw new Error('Failed to delete employee');
      }
    } catch (error) {
      console.error('Failed to delete employee:', error);
      toast.error('Failed to delete employee');
      setIsDeleting(false);
      setIsDeleteModalOpen(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  if (!employee) {
    return (
      <div className="text-center py-12">
        <h2 className="text-xl font-semibold mb-2">Employee not found</h2>
        <p className="text-gray-500 mb-6">The employee you're looking for doesn't exist or has been removed.</p>
        <Link href="/employees">
          <a>
            <Button>Return to Employees</Button>
          </a>
        </Link>
      </div>
    );
  }

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => router.push('/employees')}
            className="mb-2"
          >
            <FiArrowLeft className="mr-2" />
            Back to Employees
          </Button>
          <h1 className="text-2xl font-bold">{employee.name}</h1>
        </div>
        <div className="flex space-x-2">
          <Link href={`/employees/${id}/edit`}>
            <a>
              <Button variant="outline" className="flex items-center">
                <FiEdit className="mr-2" />
                Edit
              </Button>
            </a>
          </Link>
          <Button 
            variant="outline" 
            className="flex items-center text-red-600 border-red-200 hover:bg-red-50"
            onClick={() => setIsDeleteModalOpen(true)}
          >
            <FiTrash2 className="mr-2" />
            Delete
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Employee Profile */}
        <Card className="md:col-span-1">
          <Card.Header className="text-center pb-2">
            <div className="flex justify-center mb-4">
              <Avatar 
                fallback={employee.name} 
                size="xl" 
              />
            </div>
            <Card.Title>{employee.name}</Card.Title>
            <p className="text-gray-500 mt-1">{employee.designation}</p>
          </Card.Header>
          <Card.Content>
            <div className="space-y-4 mt-4">
              <div className="flex items-center">
                <FiMail className="text-gray-400 mr-3" />
                <div>
                  <p className="text-sm text-gray-500">Email</p>
                  <p className="font-medium">{employee.email}</p>
                </div>
              </div>
              <div className="flex items-center">
                <FiPhone className="text-gray-400 mr-3" />
                <div>
                  <p className="text-sm text-gray-500">Phone</p>
                  <p className="font-medium">{employee.phoneNumber}</p>
                </div>
              </div>
              <div className="flex items-center">
                <FiBriefcase className="text-gray-400 mr-3" />
                <div>
                  <p className="text-sm text-gray-500">Department</p>
                  {department ? (
                    <Link href={`/departments/${department.id}`}>
                      <a className="font-medium text-primary-600 hover:text-primary-700">
                        {department.name}
                      </a>
                    </Link>
                  ) : (
                    <p className="text-gray-500">No department assigned</p>
                  )}
                </div>
              </div>
            </div>
          </Card.Content>
        </Card>

        {/* Team Lead Status */}
        <Card className="md:col-span-2">
          <Card.Header>
            <Card.Title>Team Lead Status</Card.Title>
          </Card.Header>
          <Card.Content>
            {department && department.teamLeadId === employee.id ? (
              <div className="flex items-center">
                <div className="bg-green-100 text-green-800 rounded-full p-1 mr-3">
                  <FiCheck className="h-5 w-5" />
                </div>
                <div>
                  <p className="font-medium">Team Lead for {department.name}</p>
                  <p className="text-sm text-gray-500">
