import Cookies from 'js-cookie';

// Auto-authenticate user without login screen
export const autoLogin = () => {
  const user = { id: "user-auto", email: "user@example.com", role: "user" };
  Cookies.set('user', JSON.stringify(user), { expires: 1 }); // 1 day
  return true;
};

export const logout = () => {
  Cookies.remove('user');
};

export const getUser = () => {
  const userCookie = Cookies.get('user');
  if (!userCookie) {
    // Auto-login if no user cookie exists
    autoLogin();
    return { id: "user-auto", email: "user@example.com", role: "user" };
  }
  return JSON.parse(userCookie);
};

export const isAuthenticated = () => {
  if (!getUser()) {
    autoLogin();
  }
  return true;
};

export const withAuth = (gssp) => {
  return async (context) => {
    // If there is a gssp function, call it
    return gssp ? await gssp(context) : { props: {} };
  };
};
