          </div>
          <Button 
            variant="ghost" 
            size="icon" 
            onClick={onClose}
            className="h-8 w-8 rounded-full"
            aria-label="Close"
          >
            <FiX />
          </Button>
        </div>

        <div className="p-6 overflow-y-auto max-h-[60vh]">
          {children}
        </div>

        {footer && (
          <div className="p-6 border-t flex justify-end space-x-2">
            {footer}
          </div>
        )}
      </div>
    </div>,
    document.body
  );
