import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import Image from 'next/image';
import { FiLock, FiMail, FiAlertCircle } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { login, isAuthenticated } from '../lib/auth';
import { Card } from '../components/Card';
import { Input } from '../components/Input';
import { Button } from '../components/Button';
import { Label } from '../components/Label';

export default function Login() {
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const router = useRouter();

  // If already logged in, redirect to dashboard
  useEffect(() => {
    if (isAuthenticated()) {
      router.push('/');
    }
  }, [router]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    // Clear error when user starts typing
    if (error) setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      // Simple validation
      if (!formData.email) {
        throw new Error('Please enter your email');
      }

      // Call login function - now always returns true
      const success = login(formData.email, formData.password);

      if (success) {
        toast.success('Login successful!');
        // Use a timeout to ensure the toast is visible before redirect
        setTimeout(() => {
          router.push('/');
        }, 300);
      }
    } catch (err) {
      setError(err.message);
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-gray-50">
      <div className="w-full max-w-4xl grid md:grid-cols-2 shadow-xl rounded-xl overflow-hidden">
        {/* Left: Image Side */}
        <div className="hidden md:block relative bg-primary-600">
          <div className="absolute inset-0">
            <Image
              src="https://images.unsplash.com/photo-1497215728101-856f4ea42174?ixlib=rb-4.0.3&ixid=MnwxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8&auto=format&fit=crop&w=1170&q=80"
              alt="Office desk with computer"
              layout="fill"
              objectFit="cover"
              className="mix-blend-overlay opacity-20"
            />
          </div>
          <div className="relative z-10 flex flex-col justify-center p-12 text-white h-full">
            <h1 className="text-3xl font-bold mb-4">TericSoft HR</h1>
            <p className="mb-6">
              Streamline your HR operations with our comprehensive management solution.
            </p>
            <ul className="space-y-2">
              <li className="flex items-center">
                <span className="h-2 w-2 rounded-full bg-white mr-2"></span>
                Manage departments efficiently
              </li>
              <li className="flex items-center">
                <span className="h-2 w-2 rounded-full bg-white mr-2"></span>
                Track employee information
              </li>
              <li className="flex items-center">
                <span className="h-2 w-2 rounded-full bg-white mr-2"></span>
                Organize team structures
              </li>
            </ul>
          </div>
        </div>

        {/* Right: Login Form */}
        <div className="bg-white p-8 md:p-12 flex flex-col justify-center">
          <div className="text-center mb-8">
            <h2 className="text-2xl font-bold mb-2">Welcome Back</h2>
            <p className="text-gray-500">Sign in to your account</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="bg-red-50 text-red-600 p-3 rounded-md flex items-center text-sm mb-4">
                <FiAlertCircle className="mr-2 flex-shrink-0" />
                {error}
              </div>
            )}

            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
                  <FiMail />
                </div>
                <Input
                  id="email"
                  name="email"
                  type="email"
                  placeholder="Enter your email"
                  value={formData.email}
                  onChange={handleChange}
                  className="pl-10"
                  required
                  autoComplete="email"
                />
              </div>
            </div>

            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label htmlFor="password">Password</Label>
              </div>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-gray-400">
                  <FiLock />
                </div>
                <Input
                  id="password"
                  name="password"
                  type="password"
                  placeholder="••••••••"
                  value={formData.password}
                  onChange={handleChange}
                  className="pl-10"
                  autoComplete="current-password"
                />
              </div>
            </div>

