              {isLoading ? 'Deleting...' : 'Delete'}
            </Button>
          </>
        }
      >
        {employeeToDelete && (
          <div className="text-sm text-gray-500">
            <p>
              This will permanently delete the employee 
              <span className="font-semibold text-gray-700"> {employeeToDelete.name} </span>
              from the system.
            </p>
            {employeeToDelete.department && (
              <p className="mt-2">
                They will also be removed from the {employeeToDelete.department.name} department.
              </p>
            )}
          </div>
        )}
      </Modal>
    </div>
  );
}
