    "code": "import Image from 'next/image';
import { cn } from '../lib/utils';

export function Avatar({ 
  src = null, 
  alt = "Avatar", 
  size = "md", 
  className,
  fallback,
  ...props 
}) {
  const sizeClass = {
    sm: "h-8 w-8",
    md: "h-10 w-10",
    lg: "h-12 w-12",
    xl: "h-16 w-16"
  };

  // Fallback to initials if no image
  const getInitials = () => {
    if (!fallback) return "?";
    return fallback.split(" ").map(name => name[0]).join("").toUpperCase();
  };

  return (
    <div 
      className={cn(
        "relative rounded-full overflow-hidden bg-gray-200 flex items-center justify-center text-gray-600 font-medium",
        sizeClass[size],
        className
      )} 
      {...props}
    >
      {src ? (
        <Image 
          src={src} 
          alt={alt} 
          layout="fill" 
          objectFit="cover"
          className="transition-opacity duration-300 hover:opacity-90"
        />
      ) : (
        <span className="text-xs">{getInitials()}</span>
      )}
    </div>
  );
