    const distribution = departments.map(dept => ({
      id: dept.id,
      name: dept.name,
      count: getDepartmentMembers(dept.id).length
    }));

    // Sort by count (descending)
    distribution.sort((a, b) => b.count - a.count);

    // Get recent employees (would normally be sorted by join date)
    const recentEmps = [...employees].slice(0, 3);

