  "/pages/departments/[id]/edit.js": {
    "code": "import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { FiArrowLeft, FiSave } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { 
  getDepartmentById, 
  updateDepartment, 
  getEmployees 
} from '../../../lib/data';
import { Button } from '../../../components/Button';
import { Input } from '../../../components/Input';
import { Select } from '../../../components/Select';
import { Label } from '../../../components/Label';
import { Card } from '../../../components/Card';

export default function EditDepartment() {
  const [formData, setFormData] = useState({
    name: '',
    teamLeadId: ''
  });
  const [originalData, setOriginalData] = useState(null);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [employees, setEmployees] = useState([]);
  const [loading, setLoading] = useState(true);
  const router = useRouter();
  const { id } = router.query;

  useEffect(() => {
    if (id) {
      loadData();
    }
  }, [id]);

  const loadData = async () => {
    try {
      // Load department data
      const departmentData = getDepartmentById(id);

      if (!departmentData) {
        toast.error('Department not found');
        router.push('/departments');
        return;
      }

      // Load employees for team lead selection
      const employeeData = getEmployees();

      setFormData({
        name: departmentData.name,
        teamLeadId: departmentData.teamLeadId || ''
      });
      setOriginalData(departmentData);
      setEmployees(employeeData);
    } catch (error) {
      console.error('Failed to load data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Department name is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsSubmitting(true);
    try {
      const updatedDepartment = updateDepartment(id, formData);

      if (updatedDepartment) {
        toast.success(`Department "${updatedDepartment.name}" has been updated`);
        router.push(`/departments/${id}`);
      } else {
        throw new Error('Failed to update department');
      }
    } catch (error) {
      console.error('Failed to update department:', error);
      toast.error('Failed to update department');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto fade-in">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push(`/departments/${id}`)}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Department
        </Button>
        <h1 className="text-2xl font-bold">Edit Department</h1>
      </div>

      <Card>
        <form onSubmit={handleSubmit}>
          <Card.Content className="space-y-6">
            <div className="space-y-2">
              <Label htmlFor="name">
                Department Name <span className="text-red-500">*</span>
              </Label>
              <Input
                id="name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="e.g. Engineering, Marketing, HR"
                className={errors.name ? 'border-red-500' : ''}
              />
              {errors.name && (
                <p className="text-red-500 text-sm mt-1">{errors.name}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="teamLeadId">Team Lead</Label>
              <Select
                id="teamLeadId"
                name="teamLeadId"
                value={formData.teamLeadId}
                onChange={handleChange}
              >
                <option value="">-- No Team Lead --</option>
                {employees.map(emp => (
                  <option key={emp.id} value={emp.id}>
                    {emp.name} - {emp.designation}
                  </option>
                ))}
              </Select>
            </div>
          </Card.Content>

          <Card.Footer className="flex justify-end space-x-2 border-t pt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => router.push(`/departments/${id}`)}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center"
            >
              <FiSave className="mr-2" />
              {isSubmitting ? 'Saving...' : 'Save Changes'}
            </Button>
          </Card.Footer>
        </form>
      </Card>
    </div>
  );
