  "/pages/departments/new.js": {
    "code": "import { useState } from 'react';
import { useRouter } from 'next/router';
import { FiArrowLeft, FiSave } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { addDepartment, getEmployees } from '../../lib/data';
import { Button } from '../../components/Button';
import { Input } from '../../components/Input';
import { Select } from '../../components/Select';
import { Label } from '../../components/Label';
import { Card } from '../../components/Card';

export default function NewDepartment() {
  const [formData, setFormData] = useState({
    name: '',
    teamLeadId: ''
  });
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [employees, setEmployees] = useState([]);
  const router = useRouter();

  // Load employees for team lead selection
  useState(() => {
    try {
      const employeeData = getEmployees();
      setEmployees(employeeData);
    } catch (error) {
      console.error('Failed to load employees:', error);
      toast.error('Failed to load employees');
    }
  }, []);

  const validateForm = () => {
    const newErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Department name is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsSubmitting(true);
    try {
      const newDepartment = addDepartment(formData);

      toast.success(`Department "${newDepartment.name}" has been created`);
      router.push('/departments');
    } catch (error) {
      console.error('Failed to create department:', error);
      toast.error('Failed to create department');
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto fade-in">
      <div className="mb-6">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.push('/departments')}
          className="mb-2"
        >
          <FiArrowLeft className="mr-2" />
          Back to Departments
        </Button>
        <h1 className="text-2xl font-bold">Create New Department</h1>
      </div>

      <Card>
        <form onSubmit={handleSubmit}>
          <Card.Content className="space-y-6">
            <div className="space-y-2">
              <Label htmlFor="name">
                Department Name <span className="text-red-500">*</span>
              </Label>
              <Input
                id="name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="e.g. Engineering, Marketing, HR"
                className={errors.name ? 'border-red-500' : ''}
              />
              {errors.name && (
                <p className="text-red-500 text-sm mt-1">{errors.name}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="teamLeadId">Team Lead</Label>
              <Select
                id="teamLeadId"
                name="teamLeadId"
                value={formData.teamLeadId}
                onChange={handleChange}
              >
                <option value="">-- Select Team Lead (Optional) --</option>
                {employees.map(emp => (
                  <option key={emp.id} value={emp.id}>
                    {emp.name} - {emp.designation}
                  </option>
                ))}
              </Select>
              <p className="text-sm text-gray-500">
                You can assign a team lead now or update it later.
              </p>
            </div>
          </Card.Content>

          <Card.Footer className="flex justify-end space-x-2 border-t pt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => router.push('/departments')}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center"
            >
              <FiSave className="mr-2" />
              {isSubmitting ? 'Creating...' : 'Create Department'}
            </Button>
          </Card.Footer>
        </form>
      </Card>
    </div>
  );
