    "code": "
import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { 
  FiArrowLeft, FiEdit, FiTrash2, FiPlus, 
  FiUsers, FiUser, FiMail, FiPhone, FiBriefcase 
} from 'react-icons/fi';
import { toast } from 'react-toastify';
import { 
  getDepartmentById, 
  getDepartmentMembers, 
  getDepartmentTeamLead,
  deleteDepartment,
  getEmployees,
  updateEmployee
} from '../../../lib/data';
import { Button } from '../../../components/Button';
import { Card } from '../../../components/Card';
import { Avatar } from '../../../components/Avatar';
import { Modal } from '../../../components/Modal';
import { EmptyState } from '../../../components/EmptyState';
import { Select } from '../../../components/Select';
import { Label } from '../../../components/Label';

export default function DepartmentDetails() {
  const [department, setDepartment] = useState(null);
  const [members, setMembers] = useState([]);
  const [teamLead, setTeamLead] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isAddEmployeeModalOpen, setIsAddEmployeeModalOpen] = useState(false);
  const [availableEmployees, setAvailableEmployees] = useState([]);
  const [selectedEmployeeId, setSelectedEmployeeId] = useState('');
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const router = useRouter();
  const { id } = router.query;

  useEffect(() => {
    if (id) {
      loadDepartmentData();
    }
  }, [id]);

  const loadDepartmentData = () => {
    try {
      const deptData = getDepartmentById(id);

      if (!deptData) {
        toast.error('Department not found');
        router.push('/departments');
        return;
      }

      const memberData = getDepartmentMembers(id);
      const leadData = getDepartmentTeamLead(id);

      // Get available employees (employees not in this department)
      const allEmployees = getEmployees();
      const availableEmps = allEmployees.filter(emp => emp.departmentId !== id);

      setDepartment(deptData);
      setMembers(memberData);
      setTeamLead(leadData);
      setAvailableEmployees(availableEmps);
    } catch (error) {
      console.error('Failed to load department data:', error);
      toast.error('Failed to load department data');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    setIsDeleting(true);

    try {
      const success = deleteDepartment(id);

      if (success) {
        toast.success(`Department "${department.name}" has been deleted`);
        router.push('/departments');
      } else {
        throw new Error('Failed to delete department');
      }
    } catch (error) {
      console.error('Failed to delete department:', error);
      toast.error('Failed to delete department');
      setIsDeleting(false);
      setIsDeleteModalOpen(false);
    }
  };

  const handleAddEmployeeClick = () => {
    setSelectedEmployeeId('');
    setIsAddEmployeeModalOpen(true);
  };

  const handleEmployeeSelect = (e) => {
    setSelectedEmployeeId(e.target.value);
  };

  const handleAddEmployee = async () => {
    if (!selectedEmployeeId) {
      toast.error('Please select an employee');
      return;
    }

    setIsAddingEmployee(true);
    try {
      // Update the employee's department
      const updatedEmployee = updateEmployee(selectedEmployeeId, {
        departmentId: id
      });

      if (updatedEmployee) {
        toast.success(`${updatedEmployee.name} has been added to this department`);
        setIsAddEmployeeModalOpen(false);
        loadDepartmentData(); // Reload department data
      } else {
        throw new Error('Failed to add employee to department');
      }
    } catch (error) {
      console.error('Failed to add employee:', error);
      toast.error('Failed to add employee to department');
    } finally {
      setIsAddingEmployee(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  if (!department) {
    return (
      <div className="text-center py-12">
        <h2 className="text-xl font-semibold mb-2">Department not found</h2>
        <p className="text-gray-500 mb-6">The department you're looking for doesn't exist or has been removed.</p>
        <Link href="/departments">
          <a>
            <Button>Return to Departments</Button>
          </a>
        </Link>
      </div>
    );
  }

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => router.push('/departments')}
            className="mb-2"
          >
            <FiArrowLeft className="mr-2" />
            Back to Departments
          </Button>
          <h1 className="text-2xl font-bold">{department.name}</h1>
        </div>
        <div className="flex space-x-2">
          <Link href={`/departments/${id}/edit`}>
            <a>
              <Button variant="outline" className="flex items-center">
                <FiEdit className="mr-2" />
                Edit
              </Button>
            </a>
          </Link>
          <Button 
            variant="outline" 
            className="flex items-center text-red-600 border-red-200 hover:bg-red-50"
            onClick={() => setIsDeleteModalOpen(true)}
          >
            <FiTrash2 className="mr-2" />
            Delete
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Department Info */}
        <Card className="lg:col-span-1">
          <Card.Header>
            <Card.Title>Department Info</Card.Title>
          </Card.Header>
          <Card.Content>
            <div className="space-y-4">
              <div>
                <h3 className="text-sm font-medium text-gray-500">Name</h3>
                <p className="mt-1">{department.name}</p>
              </div>
              <div>
                <h3 className="text-sm font-medium text-gray-500">Members</h3>
                <p className="mt-1">{members.length} employee{members.length !== 1 ? 's' : ''}</p>
              </div>
            </div>
          </Card.Content>
        </Card>

        {/* Team Lead */}
        <Card className="lg:col-span-2">
          <Card.Header>
            <div className="flex justify-between items-center">
              <Card.Title>Team Lead</Card.Title>
              <Link href={`/departments/${id}/edit`}>
                <a>
                  <Button variant="ghost" size="sm">
                    Change
                  </Button>
                </a>
              </Link>
            </div>
          </Card.Header>
          <Card.Content>
            {teamLead ? (
              <div className="flex items-center">
                <Avatar 
                  fallback={teamLead.name} 
                  size="lg" 
                  className="mr-4"
                />
                <div>
                  <h3 className="font-medium">{teamLead.name}</h3>
                  <p className="text-gray-500">{teamLead.designation}</p>
                  <div className="flex items-center mt-2 text-sm text-gray-500">
                    <FiMail className="mr-1" />
                    <span>{teamLead.email}</span>
                  </div>
                </div>
              </div>
            ) : (
              <div className="text-center py-6 text-gray-500">
                <FiUser className="mx-auto h-12 w-12 text-gray-400 mb-3" />
                <p>No team lead assigned to this department.</p>
                <Link href={`/departments/${id}/edit`}>
                  <a>
                    <Button variant="outline" size="sm" className="mt-3">
                      Assign Team Lead
                    </Button>
                  </a>
                </Link>
              </div>
            )}
          </Card.Content>
        </Card>

        {/* Members */}
        <Card className="lg:col-span-3">
          <Card.Header>
            <div className="flex justify-between items-center">
              <Card.Title>Department Members</Card.Title>
              <Button 
                size="sm" 
                className="flex items-center"
                onClick={handleAddEmployeeClick}
              >
                <FiPlus className="mr-1" />
                Add Employee
              </Button>
            </div>
          </Card.Header>
          <Card.Content>
            {members.length === 0 ? (
              <EmptyState 
                title="No members yet"
                description="This department doesn't have any members yet. Add employees to this department."
                icon={<FiUsers className="h-12 w-12" />}
                action={handleAddEmployeeClick}
                actionText="Add Employee"
              />
            ) : (
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Employee
                      </th>
                      <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Contact
                      </th>
                      <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Designation
                      </th>
                      <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Actions
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {members.map((member) => (
                      <tr key={member.id} className="hover:bg-gray-50">
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="flex items-center">
                            <Avatar 
                              fallback={member.name} 
                              size="sm" 
                              className="mr-3"
                            />
                            <div>
                              <div className="font-medium">{member.name}</div>
                              <div className="text-sm text-gray-500">{member.email}</div>
                            </div>
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          <div className="flex items-center">
                            <FiPhone className="mr-2" />
                            {member.phoneNumber}
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm">
                          <div className="flex items-center">
                            <FiBriefcase className="mr-2 text-gray-400" />
                            {member.designation}
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm">
                          <Link href={`/employees/${member.id}`}>
                            <a className="text-primary-600 hover:text-primary-800 font-medium">
                              View
                            </a>
                          </Link>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </Card.Content>
        </Card>
      </div>

      {/* Delete Confirmation Modal */}
      <Modal
        isOpen={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        title="Delete Department"
        description="Are you sure you want to delete this department? This action cannot be undone."
        footer={
          <>
            <Button 
              variant="outline" 
              onClick={() => setIsDeleteModalOpen(false)}
              disabled={isDeleting}
            >
              Cancel
            </Button>
            <Button 
              variant="destructive" 
              onClick={handleDelete}
              disabled={isDeleting}
            >
              {isDeleting ? 'Deleting...' : 'Delete Department'}
            </Button>
          </>
        }
      >
        <div className="text-sm text-gray-500">
          <p>
            This will permanently delete the department 
            <span className="font-semibold text-gray-700"> {department.name} </span>
            and remove all department associations from its {members.length} members.
          </p>
          <p className="mt-2">
            The employees will not be deleted, but they will no longer be associated with this department.
          </p>
        </div>
      </Modal>

      {/* Add Employee Modal */}
      <Modal
        isOpen={isAddEmployeeModalOpen}
        onClose={() => setIsAddEmployeeModalOpen(false)}
        title="Add Employee to Department"
        description="Select an employee to add to this department"
        size="lg"
        footer={
          <>
            <Button 
              variant="outline" 
              onClick={() => setIsAddEmployeeModalOpen(false)}
              disabled={isAddingEmployee}
            >
              Cancel
            </Button>
            <Button 
              onClick={handleAddEmployee}
              disabled={isAddingEmployee || !selectedEmployeeId}
            >
              {isAddingEmployee ? 'Adding...' : 'Add to Department'}
            </Button>
          </>
        }
      >
        <div className="space-y-4">
          {availableEmployees.length === 0 ? (
            <div className="text-center py-6">
              <p className="text-gray-500">No available employees to add to this department.</p>
              <p className="text-sm text-gray-400 mt-2">All employees are already assigned to departments.</p>
              <Link href="/employees/new">
                <a>
                  <Button variant="outline" size="sm" className="mt-4">
                    Create New Employee
