            <>
              <div className="space-y-2">
                <Label htmlFor="employeeId">Select Employee</Label>
                <Select
                  id="employeeId"
                  value={selectedEmployeeId}
                  onChange={handleEmployeeSelect}
                  className={!selectedEmployeeId ? 'border-gray-300' : ''}
                >
                  <option value="">-- Select an Employee --</option>
                  {availableEmployees.map(emp => (
                    <option key={emp.id} value={emp.id}>
                      {emp.name} - {emp.designation}
                    </option>
                  ))}
                </Select>
              </div>

              {selectedEmployeeId && (
                <div className="bg-gray-50 p-4 rounded-md mt-4">
                  <h3 className="font-medium mb-2">Employee Details</h3>
                  {(() => {
                    const employee = availableEmployees.find(e => e.id === selectedEmployeeId);
                    return employee ? (
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
                        <div>
                          <p className="text-gray-500">Name</p>
                          <p className="font-medium">{employee.name}</p>
                        </div>
                        <div>
                          <p className="text-gray-500">Email</p>
                          <p className="font-medium">{employee.email}</p>
                        </div>
                        <div>
                          <p className="text-gray-500">Phone</p>
                          <p className="font-medium">{employee.phoneNumber}</p>
                        </div>
