import { Input } from '../../../components/Input';
import { Select } from '../../../components/Select';
import { Label } from '../../../components/Label';
import { Card } from '../../../components/Card';

export default function EditDepartment() {
  const [formData, setFormData] = useState({
    name: '',
    teamLeadId: ''
  });
  const [originalData, setOriginalData] = useState(null);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [employees, setEmployees] = useState([]);
  const [loading, setLoading] = useState(true);
  const router = useRouter();
  const { id } = router.query;

  useEffect(() => {
    if (id) {
      loadData();
    }
  }, [id]);

  const loadData = async () => {
    try {
      // Load department data
      const departmentData = getDepartmentById(id);

      if (!departmentData) {
        toast.error('Department not found');
        router.push('/departments');
        return;
      }

      // Load employees for team lead selection
      const employeeData = getEmployees();

      setFormData({
        name: departmentData.name,
        teamLeadId: departmentData.teamLeadId || ''
      });
      setOriginalData(departmentData);
      setEmployees(employeeData);
    } catch (error) {
      console.error('Failed to load data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Department name is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // Clear error when field is edited
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsSubmitting(true);
    try {
      const updatedDepartment = updateDepartment(id, formData);

      if (updatedDepartment) {
        toast.success(`Department "${updatedDepartment.name}" has been updated`);
        router.push(`/departments/${id}`);
      } else {
        throw new Error('Failed to update department');
      }
    } catch (error) {
      console.error('Failed to update department:', error);
      toast.error('Failed to update department');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-600"></div>
