import Cookies from 'js-cookie';

const ADMIN_EMAIL = 'admin@example.com';
const ADMIN_PASSWORD = 'admin123'; // In a real app, this would be securely stored

export const login = async (email, password) => {
  // Simple mock login
  if (email === ADMIN_EMAIL && password === ADMIN_PASSWORD) {
    const user = {
      id: '1',
      email: email,
      role: 'admin'
    };

    // Store user in cookie
    Cookies.set('user', JSON.stringify(user), { expires: 7 });
    return user;
  }

  throw new Error('Invalid email or password');
};

export const logout = async () => {
  Cookies.remove('user');
};

export const getUser = async () => {
  const userCookie = Cookies.get('user');

  if (!userCookie) {
    return null;
  }

  try {
    const user = JSON.parse(userCookie);
    return user.role === 'admin' ? user : null;
  } catch (error) {
    console.error('Error parsing user cookie:', error);
    return null;
  }
};

export const isAuthenticated = async () => {
  const user = await getUser();
  return user !== null && user.role === 'admin';
};

export const withAuth = (gssp) => {
  return async (context) => {
    // Check if user is authenticated and is admin
    const cookies = context.req.headers.cookie || '';
    let isAuth = false;

    // Manually parse cookies to find user
    if (cookies.includes('user=')) {
      try {
        const userCookieStr = cookies
          .split('; ')
          .find(row => row.startsWith('user='))
          .split('=')[1];

        const user = JSON.parse(decodeURIComponent(userCookieStr));
        isAuth = user && user.role === 'admin';
      } catch (error) {
        console.error('Error parsing user from cookies:', error);
      }
    }

    if (!isAuth) {
      // Redirect to login page if not authenticated
      return {
        redirect: {
          destination: '/login',
          permanent: false,
        },
      };
    }

    // If there is a gssp function, call it
    return gssp ? await gssp(context) : { props: {} };
  };
};
